#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Diagnoses and fixes two things in "The Journey - Milwaukee to Mayapur"
story screen:
  1. Moves the English/বাংলা/हिन्दी language selector from below "THE
     LESSON" to directly below the chapter title, before "THE STORY".
  2. Verifies that all 13 stages actually have their Bengali/Hindi story
     text present in the data (this was never confirmed after the first
     script ran), and re-applies it for any stage where it's missing —
     using the exact same text as before, nothing shortened or reworded.

Honest limitation, stated here rather than worked around: only STORY text
was ever provided in Bengali/Hindi -- no Bengali/Hindi LESSON text was
supplied. This script makes the story switch correctly in all three
languages; the Lesson section will continue to show in English only,
since translating it would mean generating text that was never provided.

Usage:
    python3 fix_language_selector.py
"""
import re, sys, os

TARGET = "www/index.html"

if not os.path.isfile(TARGET):
    print("ERROR: could not find " + TARGET + ". Run this from your repo root.")
    sys.exit(1)

with open(TARGET, "r", encoding="utf-8") as f:
    html = f.read()

TITLES_IN_ORDER = [
"Early Life Before Monasticism","The Search for Krishna","An ISKCON Pioneer",
"India and Beyond","The Lord's Eternal Associate","Mayapur—The Early Days",
"Distributing Divine Grace","The Temple of the Vedic Planetarium",
"Srila Prabhupada's Departure","Namahatta—The Marketplace of the Holy Name",
"World Travels","Attacked with a Knife","Invincible",
]

BENGALI = [
"জয়পতাকা স্বামী উইসকনসিনের মিলওয়াকিতে এক সমৃদ্ধ খ্রিস্টান পরিবারে গর্ডন জন নামে জন্মগ্রহণ করেন। শৈশব থেকেই তিনি বুদ্ধিমত্তা, সহমর্মিতা এবং আধ্যাত্মিক অনুসন্ধিৎসার পরিচয় দিয়েছিলেন। একটি কাঠবিড়ালির আকস্মিক মৃত্যুর ঘটনা তাঁকে জীবনের মূল্য সম্পর্কে গভীরভাবে চিন্তা করতে উদ্বুদ্ধ করেছিল। যদিও তিনি কেমিক্যাল ইঞ্জিনিয়ারিং অধ্যয়নের জন্য ব্রাউন ইউনিভার্সিটিতে ভর্তি হয়েছিলেন, তথাপি শিক্ষাগত ও জাগতিক সাফল্য তাঁকে পরিতৃপ্ত করতে পারেনি। চেতনা, ধর্ম এবং আত্ম-উপলব্ধির প্রতি তাঁর আগ্রহ ক্রমশ বৃদ্ধি পেতে থাকে। অবশেষে, আধ্যাত্মিক সত্যের সন্ধানে তিনি বিশ্ববিদ্যালয় এবং পারিবারিক ব্যবসা ত্যাগ করেন। তাঁর এই অনুসন্ধান তাঁকে ক্যালিফোর্নিয়ায় নিয়ে যায়, যেখানে তিনি বিভিন্ন আধ্যাত্মিক আন্দোলন সম্পর্কে অনুসন্ধান করেন এবং শেষ পর্যন্ত এমন এক পথের সন্ধান পান, যা তাঁর সমগ্র জীবনকে রূপান্তরিত করে দেয়।",
"১৯৬০-এর দশকের শেষভাগের সাংস্কৃতিক পরিবর্তনের সময়, জয়পতাকা স্বামী প্রকৃত আধ্যাত্মিক জ্ঞানের সন্ধানে ক্যালিফোর্নিয়ায় ভ্রমণ করেন। তিনি বিভিন্ন যোগগোষ্ঠীতে গিয়েছিলেন, কিন্তু তাদের শিক্ষকেরা নিজেদের প্রচারিত নীতিগুলি অনুসরণ করতে ব্যর্থ হওয়ায় তিনি হতাশ হয়ে পড়েন। সান ফ্রান্সিসকোতে হরে কৃষ্ণ রথযাত্রা মহোৎসবে অংশগ্রহণ করার পর তাঁর জীবন পরিবর্তিত হয়ে যায়। হরিনাম সংকীর্তন, নৃত্য, প্রসাদ এবং আনন্দময় ভক্তি তাঁকে গভীরভাবে আকৃষ্ট করে। তিনি নিয়মিত মন্দিরে যেতে শুরু করেন এবং ‘ভক্ত জয়’ নামে পরিচিত হয়ে ওঠেন। পরবর্তীতে তিনি মন্ট্রিয়লে যান, যেখানে শ্রীল প্রভুপাদ প্রচারকার্য পরিচালনা করছিলেন। হরে কৃষ্ণ আন্দোলনের মাধ্যমে তিনি শ্রীকৃষ্ণের পবিত্র নাম জপ, ভক্তিমূলক সেবা এবং শ্রীচৈতন্য মহাপ্রভুর শিক্ষানুসরণের উপর প্রতিষ্ঠিত এক বাস্তব ও কার্যকর আধ্যাত্মিক পথের সন্ধান লাভ করেন।",
"জয়পতাকা স্বামী প্রথমবার মন্ট্রিয়লে একটি প্রবচনের সময় শ্রীল প্রভুপাদের দর্শন লাভ করেন। তিনি তৎক্ষণাৎ উপলব্ধি করেন যে, প্রভুপাদ একজন প্রামাণিক আধ্যাত্মিক গুরু। দীক্ষা গ্রহণের পর তাঁকে ‘জয়পতাকা দাস’ নাম প্রদান করা হয়। তিনি নিয়মিত হরিনাম জপ করা, চারটি নিয়মনীতি অনুসরণ করা এবং ভগবানের সকল আন্তরিক সেবককে সম্মান করতে শেখেন। তখনও তিনি একজন নবীন ভক্ত হওয়া সত্ত্বেও, প্রবীণ সদস্যরা চলে গেলে তাঁকে মন্ট্রিয়ল মন্দিরের সভাপতি নিযুক্ত করা হয়। তিনি কারখানায় কাজ করেন, মন্দিরের ব্যয় নির্বাহে সহায়তা করেন এবং ভক্তিমূলক সাহিত্য মুদ্রণের কাজেও অংশগ্রহণ করেন। দৃঢ় সংকল্প, শৃঙ্খলা এবং শ্রীল প্রভুপাদের সঙ্গে নিয়মিত যোগাযোগের মাধ্যমে তিনি শক্তিশালী নেতৃত্বের গুণাবলি বিকশিত করেন। কঠিন দায়িত্ব গ্রহণে তাঁর আগ্রহ ও প্রস্তুতি তাঁকে ইসকনের প্রারম্ভিক বিকাশে একজন গুরুত্বপূর্ণ অগ্রদূতে পরিণত করে।",
"কানাডায় সেবা করার পর জয়পতাকা স্বামী শ্রীল প্রভুপাদের কাছ থেকে ভারতে যাওয়ার নির্দেশ লাভ করেন। প্রভুপাদ তাঁকে অন্যান্য ভক্তদের সঙ্গে ধৈর্যসহকারে সহযোগিতা করতে এবং কৃষ্ণভাবনামৃতের প্রসারে সহায়তা করতে উপদেশ দেন। ভারতে এসে তিনি বাংলা ভাষা শেখেন, সর্বসাধারণের মধ্যে হরিনাম সংকীর্তনে অংশগ্রহণ করেন এবং ইসকনের স্বাধীন কার্যক্রম প্রতিষ্ঠায় সহায়তা করেন। ১৯৭০ সালে, মাত্র চব্বিশ বছর বয়সে, তিনি ত্যাগময় জীবনের আশ্রম অর্থাৎ সন্ন্যাস গ্রহণ করেন এবং ‘জয়পতাকা স্বামী’ নামে পরিচিত হন। তিনি অত্যন্ত সাধারণ ও সীমিত সুযোগ-সুবিধার মধ্যেও কলকাতা ও মায়াপুরে ইসকনের কার্যক্রমে সহায়তা করেন। আর্থিক সংকট ও সীমিত সুযোগ-সুবিধা সত্ত্বেও তাঁর উৎসাহ অটুট ছিল। তিনি কৃষিকাজ করেন, স্থানীয় রীতিনীতি সম্পর্কে শিক্ষা লাভ করেন এবং ভারতে শ্রীল প্রভুপাদের মিশনের বাস্তব ভিত্তি প্রতিষ্ঠায় সহায়তা করেন।",
"জয়পতাকা স্বামী কলকাতা মন্দিরের সভাপতি হিসেবে সেবা করার পাশাপাশি মায়াপুরে ইসকনের কেন্দ্র বিকাশে সহায়তা করেন। তিনি বাংলা ভাষা শেখেন, কৃষিকাজে অংশগ্রহণ করেন এবং নির্মাণ ও ব্যবস্থাপনা সংক্রান্ত শ্রীল প্রভুপাদের নির্দেশাবলি অনুসরণ করেন। কুম্ভমেলার সময় তিনি প্রভুপাদের অমূল্য ব্যক্তিগত সঙ্গ লাভ করেন এবং আধ্যাত্মিক নেতৃবৃন্দ ও সাধারণ মানুষের প্রতি তাঁর করুণাময় আচরণ প্রত্যক্ষ করেন। তিনি নানা বিপজ্জনক পরিস্থিতিরও সম্মুখীন হন, যার মধ্যে নির্মাণকাজে বিঘ্ন ঘটানো একটি গোখরা সাপকে সরিয়ে দেওয়ার ঘটনাও ছিল। বাংলায় যুদ্ধ ও বন্যার সময় জয়পতাকা স্বামী এবং অন্যান্য ভক্ত দুঃখ-কষ্টে থাকা গ্রামবাসীদের মধ্যে প্রসাদ বিতরণ করেন। শ্রীল প্রভুপাদ প্রকাশ্যে তাঁর নিবেদিত সেবার প্রশংসা করেন, এবং বহু ভক্ত শ্রীচৈতন্য মহাপ্রভুর আধ্যাত্মিক মিশনের সঙ্গে তাঁর গভীর সম্পর্ক উপলব্ধি করেন।",
"প্রারম্ভিক মায়াপুর সম্প্রদায়টি কয়েকটি সাধারণ কুটির, কৃষিজমি এবং অল্পসংখ্যক ভক্ত নিয়ে গঠিত ছিল। শ্রীল প্রভুপাদ চেয়েছিলেন মায়াপুর যেন ইসকনের আন্তর্জাতিক প্রধান কেন্দ্র এবং আধ্যাত্মিক শিক্ষার একটি গুরুত্বপূর্ণ কেন্দ্র হয়ে ওঠে। জয়পতাকা স্বামী জমির উন্নয়ন, কৃষিকাজ, নির্মাণ, অতিথি-সুবিধা এবং শ্রীবিগ্রহের সেবার বিকাশে সহায়তা করেন। ভক্তরা সাধারণ জীবনযাত্রায় সন্তুষ্ট থাকলেও, প্রভুপাদ তাঁদের দর্শনার্থীদের জন্য যথাযথ ভবন নির্মাণের নির্দেশ দেন। তিনি ব্যাখ্যা করেছিলেন যে, কৃষ্ণভাবনামৃতের প্রচার এবং তা অন্যদের সঙ্গে ভাগ করে নেওয়া আধ্যাত্মিক জীবনের কেন্দ্রীয় কর্তব্য। জয়পতাকা স্বামী দৃঢ়তার সঙ্গে এই নির্দেশগুলি অনুসরণ করেন। কঠোর পরিশ্রম, পারস্পরিক সহযোগিতা এবং বিশ্বাসের মাধ্যমে তিনি একটি অনুন্নত গ্রামীণ অঞ্চলকে শ্রীচৈতন্য মহাপ্রভুর প্রতি নিবেদিত বিশ্বব্যাপী আধ্যাত্মিক সম্প্রদায়ের ভিত্তিতে রূপান্তরিত করতে সহায়তা করেন।",
"শ্রীল প্রভুপাদ মায়াপুর প্রকল্পের নাম দেন ‘মায়াপুর চন্দ্রোদয়’, যার অর্থ মায়াপুরের উদীয়মান চন্দ্র। এটি সমগ্র বিশ্বে শ্রীচৈতন্য মহাপ্রভুর শীতল ও প্রশান্তিদায়ক কৃপার প্রসারের প্রতীক ছিল। জয়পতাকা স্বামী প্রচার, শিক্ষা এবং প্রসাদ বিতরণের মাধ্যমে এই দর্শনকে বাস্তবে রূপ দিতে সহায়তা করেন। প্রভুপাদ নির্দেশ দিয়েছিলেন যে, মায়াপুর মন্দিরের আশেপাশে বসবাসকারী কোনো মানুষ যেন ক্ষুধার্ত না থাকে। এই নির্দেশের অনুপ্রেরণায় এমন সুসংগঠিত কর্মসূচি গড়ে ওঠে, যার মাধ্যমে গ্রামবাসী ও তীর্থযাত্রীদের বিনামূল্যে অথবা সাশ্রয়ী মূল্যে পবিত্র প্রসাদ প্রদান করা হতো। জয়পতাকা স্বামী ভক্তিমূলক আদর্শসমূহও রক্ষা করেন এবং বৈদিক দর্শন ব্যাখ্যা করার উদ্দেশ্যে শিক্ষামূলক প্রদর্শনী পরিকল্পনায় সহায়তা করেন। এই অধ্যায়ে মায়াপুরকে একটি বিকাশমান আধ্যাত্মিক নগরী হিসেবে উপস্থাপন করা হয়েছে, যেখানে পূজা-অর্চনা, শিক্ষা, করুণাময় প্রসাদ বিতরণ এবং ভক্তিমূলক সংস্কৃতির মাধ্যমে বিশ্বের প্রতিটি দেশের মানুষকে সেবা করা হবে।",
"‘টেম্পল অব দ্য বৈদিক প্ল্যানেটোরিয়াম’ ছিল মায়াপুরকে কেন্দ্র করে শ্রীল প্রভুপাদের এক মহান দর্শন। তিনি চেয়েছিলেন স্থাপত্য, মডেল, শিল্পকর্ম এবং শিক্ষার মাধ্যমে সেখানে বৈদিক বিশ্বতত্ত্ব, দর্শন এবং আধ্যাত্মিক জগতের ধারণা উপস্থাপিত হোক। এই মন্দিরের উদ্দেশ্য ছিল বিশ্বের বিভিন্ন প্রান্ত থেকে দর্শনার্থীদের আকৃষ্ট করা এবং তাঁদের কাছে শ্রীমদ্ভাগবতের শিক্ষা ব্যাখ্যা করা। এর উন্নয়নের পথে আর্থিক, রাজনৈতিক এবং কারিগরি নানা প্রতিবন্ধকতা দেখা দেয়। তবুও জয়পতাকা স্বামী এই প্রকল্পকে সমর্থন ও প্রচার করে যেতে থাকেন, কারণ তিনি এটিকে প্রভুপাদের একটি গুরুত্বপূর্ণ নির্দেশ হিসেবে বিবেচনা করতেন। এছাড়াও তিনি ‘ভক্তিবেদান্ত স্বামী চ্যারিটি ট্রাস্ট’-এর সঙ্গে কাজ করে শ্রীচৈতন্য মহাপ্রভু এবং গৌড়ীয় বৈষ্ণব পরম্পরার সঙ্গে সম্পর্কিত পবিত্র স্থানগুলি চিহ্নিত করা, পুনরুদ্ধার করা এবং সংরক্ষণের কাজে অংশগ্রহণ করেন।",
"জয়পতাকা স্বামী ভক্তিবেদান্ত স্বামী চ্যারিটি ট্রাস্টের মাধ্যমে পবিত্র স্থানসমূহ সংরক্ষণে সহায়তা করেন এবং ইসকনের গভর্নিং বডি কমিশনের সদস্য হিসেবে সেবা করেন। বৃন্দাবনে শ্রীল প্রভুপাদের অন্তিম অসুস্থতার সময় তিনি অন্যান্য শিষ্যদের সঙ্গে হরিনাম জপ, তাঁর অঙ্গমর্দন এবং ব্যক্তিগত সেবার মাধ্যমে তাঁদের আধ্যাত্মিক গুরুর সেবা করেন। প্রভুপাদের অপ্রকট হওয়ার পূর্বে জয়পতাকা স্বামী তাঁর চরণকমলে প্রার্থনা করেন, যেন তাঁর মিশন চালিয়ে যাওয়ার শক্তি তিনি লাভ করেন। প্রভুপাদের অপ্রকট হওয়ার পর তিনি সমাধি অনুষ্ঠানে অংশগ্রহণ করেন এবং গভীর ব্যক্তিগত শোকের সম্মুখীন হন। প্রভুপাদ তাঁকে শিষ্যদের দীক্ষা দেওয়া এবং নতুন ভক্তদের পথনির্দেশ করার অনুমোদন প্রদান করেছিলেন। জয়পতাকা স্বামী সেই দায়িত্ব গ্রহণ করেন এবং পরবর্তীতে গৃহস্থ-ভিত্তিক ভক্ত সম্প্রদায়ের প্রসারের একটি কার্যকর মাধ্যম হিসেবে নামহট্ট পদ্ধতির বিকাশ ঘটান।",
"জয়পতাকা স্বামী শ্রীল ভক্তিবিনোদ ঠাকুর কর্তৃক মূলত প্রচারিত নামহট্ট ব্যবস্থাকে পুনরুজ্জীবিত ও সম্প্রসারিত করেন। ‘নামহট্ট’ অর্থ ‘পবিত্র নামের বাজার’। এই ব্যবস্থা গৃহস্থ ভক্তদের আশ্রমের বাইরে বসবাস করেও কৃষ্ণভাবনামৃত অনুশীলন, পরিবার প্রতিপালন, গৃহে আধ্যাত্মিক অনুষ্ঠান আয়োজন এবং মন্দিরসমূহকে সহায়তা করার সুযোগ প্রদান করে। জয়পতাকা স্বামী গুরুত্বপূর্ণ গৌড়ীয় বৈষ্ণব গ্রন্থ অনুবাদ ও ব্যাখ্যা করেন এবং ভক্তদের অংশগ্রহণের জন্য সুসংগঠিত বিভিন্ন স্তর গড়ে তোলেন। বিশ্বাস, ভক্তি এবং শ্রীকৃষ্ণের প্রতি প্রেমের আধ্যাত্মিক স্তরগুলিকে একটি বাজারের ক্রমবর্ধমান মূল্যবান পণ্যের সঙ্গে তুলনা করা হয়েছিল। নামহট্ট এবং সংশ্লিষ্ট ভক্তিবৃক্ষ কর্মসূচির মাধ্যমে ভারত ও অন্যান্য দেশে হাজার হাজার ক্ষুদ্র ভক্তগোষ্ঠী গড়ে ওঠে। এই কর্মসূচিগুলি পরিবার এবং স্থানীয় সম্প্রদায়ের জন্য আধ্যাত্মিক অনুশীলনকে সহজলভ্য করে তোলে।",
"জয়পতাকা স্বামী মধ্যপ্রাচ্য, ইউরোপ, আমেরিকা এবং অন্যান্য অঞ্চলে কৃষ্ণভাবনামৃতের প্রসারের উদ্দেশ্যে ব্যাপকভাবে ভ্রমণ করেন। যেসব দেশে প্রকাশ্যে প্রচারকার্য সীমাবদ্ধ ছিল, সেখানে ভক্তরা ব্যক্তিগত গৃহে অনুষ্ঠান আয়োজন করতেন, অনূদিত গ্রন্থ বিতরণ করতেন এবং ঘরের অভ্যন্তরে বিভিন্ন উৎসব উদ্‌যাপন করতেন। জয়পতাকা স্বামী ব্যক্তিগত সফর, দিকনির্দেশনা এবং যোগাযোগের মাধ্যমে এসব সম্প্রদায়কে উৎসাহিত করতেন। তিনি বিশ্বের বিভিন্ন প্রান্তের অনুসারীদের কাছে সহজলভ্য থাকার জন্য প্রাথমিক সময় থেকেই ই-মেইল ব্যবহার করতেন। এই অধ্যায়ে আটলান্টায় অনুষ্ঠিত পানিহাটি চিড়া-দধি মহোৎসবে তাঁর সম্পৃক্ততার বর্ণনা রয়েছে, যা ‘নিউ পানিহাটি ধাম’ নামে পরিচিত। তাঁর নির্দেশনায় এটি রথযাত্রা, হরিনাম সংকীর্তন, পূজা, প্রসাদ এবং আধ্যাত্মিক শিক্ষায় সমৃদ্ধ এক বৃহৎ ভক্তিমূলক মহোৎসবে পরিণত হয়। তাঁর ভ্রমণ শ্রীল প্রভুপাদের মিশনকে কেন্দ্র করে আন্তর্জাতিক ভক্ত সম্প্রদায়সমূহকে ঐক্যবদ্ধ করতে সহায়তা করে।",
"১৯৮৯ সালে মাদ্রিদ থেকে বার্সেলোনা যাওয়ার পথে জয়পতাকা স্বামী পেছন থেকে আক্রমণের শিকার হন। এক ব্যক্তি তাঁর গলার ওপর গভীরভাবে ছুরি চালায়, যার ফলে গুরুত্বপূর্ণ রক্তনালিগুলি ক্ষতিগ্রস্ত হয়। প্রচণ্ড রক্তক্ষরণ হওয়া এবং কথা বলতে অক্ষম হওয়া সত্ত্বেও তিনি নিজের বস্ত্র দিয়ে ক্ষতস্থানটি পেঁচিয়ে রাখেন এবং মনে মনে হরে কৃষ্ণ মহামন্ত্র জপ করতে থাকেন। তিনি শ্রীল প্রভুপাদ এবং মায়াপুরে তাঁর অসমাপ্ত দায়িত্বসমূহ স্মরণ করেন। জরুরি অস্ত্রোপচারের মাধ্যমে তাঁর জীবন রক্ষা পায় এবং চিকিৎসকেরা তাঁর বেঁচে যাওয়াকে অসাধারণ বলে বিবেচনা করেন। প্রথমদিকে কিছু মিথ্যা প্রতিবেদনে আক্রমণকারীকে ইসকনের সঙ্গে যুক্ত করা হয়েছিল; কিন্তু জয়পতাকা স্বামী হাসপাতাল থেকেই সংবাদ সম্মেলনে অংশগ্রহণ করে সেই ভুল তথ্য সংশোধন করেন। সারা বিশ্বের ভক্তরা তাঁর জন্য প্রার্থনা করেন। চিকিৎসা ও পুনর্বাসনের পর তিনি নতুন দৃঢ় সংকল্প নিয়ে পুনরায় ভ্রমণ, শিক্ষা প্রদান এবং প্রচারকার্যে আত্মনিয়োগ করেন।",
"২০০৮ সালে মুম্বাইয়ে জয়পতাকা স্বামী গুরুতর মস্তিষ্কে রক্তক্ষরণের শিকার হন। তিনি তাঁর চলাফেরা এবং বাকশক্তির অনেকটাই হারিয়ে ফেলেন, কিন্তু নিজের আধ্যাত্মিক কর্তব্য সম্পর্কে সচেতন ছিলেন। তাঁর প্রথম দিককার অনুরোধগুলির একটি ছিল একটি গণনার যন্ত্র, যাতে তিনি হরিনাম জপ চালিয়ে যেতে পারেন। নিবিড় চিকিৎসা এবং পুনর্বাসনের মাধ্যমে তিনি ধীরে ধীরে সুস্থ হয়ে ওঠেন এবং পুনরায় প্রচারকার্য শুরু করেন। তিনি প্রতিটি শারীরিক ব্যায়ামকে শ্রীকৃষ্ণের পবিত্র নামের সঙ্গে যুক্ত করতেন। পরবর্তীতে তাঁর যকৃৎ ও বৃক্কে গুরুতর সমস্যা দেখা দেয়, যার একটি কারণ ছিল পূর্ববর্তী রক্তসঞ্চালনের মাধ্যমে সংক্রমিত হেপাটাইটিস। ২০১৮ সালে তাঁর সফলভাবে যকৃৎ ও বৃক্ক প্রতিস্থাপন করা হয়। শারীরিক সীমাবদ্ধতা অব্যাহত থাকা এবং হুইলচেয়ার ব্যবহার করা সত্ত্বেও, জয়পতাকা স্বামী ভ্রমণ, শিষ্যদের শিক্ষা প্রদান এবং শ্রীল প্রভুপাদের মায়াপুর মিশনের সেবা অব্যাহত রাখেন।",
]

HINDI = [
"जयपताका स्वामी का जन्म विस्कॉन्सिन के मिलवॉकी नगर में एक समृद्ध ईसाई परिवार में गॉर्डन जॉन के रूप में हुआ था। बाल्यकाल से ही उन्होंने बुद्धिमत्ता, करुणा और आध्यात्मिक जिज्ञासा का परिचय दिया। एक गिलहरी की आकस्मिक मृत्यु की घटना ने उन्हें जीवन के मूल्य के विषय में गहराई से विचार करने के लिए प्रेरित किया। यद्यपि उन्होंने केमिकल इंजीनियरिंग का अध्ययन करने के लिए ब्राउन यूनिवर्सिटी में प्रवेश लिया, फिर भी शैक्षणिक और भौतिक सफलता उन्हें संतुष्ट नहीं कर सकी। चेतना, धर्म और आत्म-साक्षात्कार के प्रति उनकी रुचि निरंतर बढ़ती गई। अंततः आध्यात्मिक सत्य की खोज में उन्होंने विश्वविद्यालय और अपने पारिवारिक व्यवसाय को छोड़ दिया। उनकी यह यात्रा उन्हें कैलिफ़ोर्निया ले गई, जहाँ उन्होंने विभिन्न आध्यात्मिक आंदोलनों का अन्वेषण किया और अंततः उस मार्ग को पाया, जिसने उनके संपूर्ण जीवन को परिवर्तित कर दिया।",
"1960 के दशक के अंतिम वर्षों में हो रहे सांस्कृतिक परिवर्तनों के बीच, जयपताका स्वामी वास्तविक आध्यात्मिक ज्ञान की खोज में कैलिफ़ोर्निया गए। उन्होंने विभिन्न योग समूहों का भ्रमण किया, किंतु जब उन्होंने देखा कि उनके शिक्षक स्वयं उन सिद्धांतों का पालन नहीं करते जिन्हें वे दूसरों को सिखाते थे, तो वे निराश हो गए। सैन फ़्रांसिस्को में हरे कृष्ण रथ-यात्रा महोत्सव में सम्मिलित होने के बाद उनका जीवन परिवर्तित हो गया। हरिनाम संकीर्तन, नृत्य, प्रसाद और आनंदमय भक्ति ने उन्हें अत्यंत गहराई से आकर्षित किया। वे नियमित रूप से मंदिर जाने लगे और ‘भक्त जय’ के नाम से पहचाने जाने लगे। बाद में वे मॉन्ट्रियल गए, जहाँ श्रील प्रभुपाद प्रचार कर रहे थे। हरे कृष्ण आंदोलन के माध्यम से उन्हें श्रीकृष्ण के पवित्र नामों के जप, भक्ति-सेवा और श्री चैतन्य महाप्रभु की शिक्षाओं के अनुसरण पर आधारित एक व्यावहारिक आध्यात्मिक मार्ग प्राप्त हुआ।",
"जयपताका स्वामी ने पहली बार मॉन्ट्रियल में एक प्रवचन के दौरान श्रील प्रभुपाद का दर्शन किया। उन्होंने तुरंत पहचान लिया कि प्रभुपाद एक प्रामाणिक आध्यात्मिक गुरु हैं। दीक्षा प्राप्त करने के पश्चात उन्हें ‘जयपताका दास’ नाम प्रदान किया गया। उन्होंने नियमित रूप से हरिनाम जप करना, चार नियामक सिद्धांतों का पालन करना और भगवान के सभी निष्कपट सेवकों का सम्मान करना सीखा। यद्यपि वे अभी एक नए भक्त ही थे, फिर भी वरिष्ठ सदस्यों के चले जाने पर उन्हें मॉन्ट्रियल मंदिर का अध्यक्ष नियुक्त कर दिया गया। उन्होंने कारखानों में कार्य किया, मंदिर के खर्चों में सहयोग दिया और भक्ति-साहित्य के मुद्रण में सहायता की। दृढ़ संकल्प, अनुशासन और श्रील प्रभुपाद के साथ नियमित संवाद के माध्यम से उनमें सशक्त नेतृत्व के गुण विकसित हुए। कठिन उत्तरदायित्वों को स्वीकार करने की उनकी तत्परता ने उन्हें इस्कॉन के प्रारम्भिक विकास का एक महत्वपूर्ण अग्रदूत बना दिया।",
"कनाडा में सेवा करने के पश्चात जयपताका स्वामी को श्रील प्रभुपाद से भारत जाने का निर्देश प्राप्त हुआ। प्रभुपाद ने उन्हें अन्य भक्तों के साथ धैर्यपूर्वक सहयोग करने और कृष्णभावनामृत के विस्तार में सहायता करने का उपदेश दिया। भारत में उन्होंने बंगाली भाषा सीखी, सार्वजनिक हरिनाम संकीर्तन में भाग लिया और इस्कॉन की स्वतंत्र गतिविधियों को स्थापित करने में सहायता की। सन् 1970 में, केवल चौबीस वर्ष की आयु में, उन्होंने त्यागमय जीवन का आश्रम अर्थात् संन्यास स्वीकार किया और ‘जयपताका स्वामी’ के नाम से प्रसिद्ध हुए। उन्होंने अत्यंत साधारण परिस्थितियों में कलकत्ता और मायापुर में इस्कॉन के कार्यों में सहायता की। आर्थिक कठिनाइयों और सीमित सुविधाओं के बावजूद उनका उत्साह बना रहा। उन्होंने कृषि कार्य किया, स्थानीय रीति-रिवाजों का अध्ययन किया और भारत में श्रील प्रभुपाद के मिशन की व्यावहारिक नींव स्थापित करने में सहयोग दिया।",
"जयपताका स्वामी ने कलकत्ता मंदिर के अध्यक्ष के रूप में सेवा करते हुए मायापुर में इस्कॉन के केंद्र के विकास में भी सहयोग दिया। उन्होंने बंगाली भाषा सीखी, कृषि कार्य किया और निर्माण तथा प्रबंधन से संबंधित श्रील प्रभुपाद के निर्देशों का पालन किया। कुंभ मेले के समय उन्हें प्रभुपाद का बहुमूल्य व्यक्तिगत संग प्राप्त हुआ और उन्होंने आध्यात्मिक नेताओं तथा सामान्य लोगों के प्रति उनके करुणामय व्यवहार को देखा। उन्होंने कई खतरनाक परिस्थितियों का भी सामना किया, जिनमें निर्माण कार्य में बाधा उत्पन्न करने वाले एक कोबरा साँप को हटाना भी सम्मिलित था। बंगाल में युद्ध और बाढ़ के समय जयपताका स्वामी तथा अन्य भक्तों ने पीड़ित ग्रामीणों को प्रसाद वितरित किया। श्रील प्रभुपाद ने सार्वजनिक रूप से उनकी समर्पित सेवा की प्रशंसा की, और अनेक भक्तों ने श्री चैतन्य महाप्रभु के आध्यात्मिक मिशन के साथ उनके गहरे संबंध को पहचाना।",
"प्रारम्भिक मायापुर समुदाय में साधारण झोपड़ियाँ, कृषि-भूमि और थोड़े से भक्त थे। श्रील प्रभुपाद चाहते थे कि मायापुर इस्कॉन का अंतरराष्ट्रीय मुख्यालय तथा आध्यात्मिक शिक्षा का एक प्रमुख केंद्र बने। जयपताका स्वामी ने भूमि के विकास, कृषि, निर्माण, अतिथि-सुविधाओं और श्रीविग्रह की सेवा को विकसित करने में सहायता की। यद्यपि भक्त एक साधारण जीवनशैली से संतुष्ट थे, प्रभुपाद ने उन्हें आगंतुकों के लिए उचित भवनों का निर्माण करने का निर्देश दिया। उन्होंने समझाया कि कृष्णभावनामृत का प्रचार करना और उसे दूसरों के साथ बाँटना प्रमुख आध्यात्मिक कर्तव्य हैं। जयपताका स्वामी ने दृढ़ निश्चय के साथ इन निर्देशों का पालन किया। कठोर परिश्रम, सहयोग और श्रद्धा के माध्यम से उन्होंने एक अविकसित ग्रामीण क्षेत्र को श्री चैतन्य महाप्रभु को समर्पित एक विश्वव्यापी आध्यात्मिक समुदाय की नींव में परिवर्तित करने में सहायता की।",
"श्रील प्रभुपाद ने मायापुर परियोजना का नाम ‘मायापुर चन्द्रोदय’ रखा, जिसका अर्थ है मायापुर का उदित होता चन्द्रमा। यह सम्पूर्ण विश्व में श्री चैतन्य महाप्रभु की शीतल कृपा के प्रसार का प्रतीक था। जयपताका स्वामी ने प्रचार, शिक्षा और प्रसाद वितरण के माध्यम से इस दर्शन को व्यावहारिक रूप देने में सहायता की। प्रभुपाद ने निर्देश दिया था कि मायापुर मंदिर के आसपास रहने वाला कोई भी व्यक्ति भूखा न रहे। इस निर्देश से प्रेरित होकर सुव्यवस्थित कार्यक्रम आरम्भ किए गए, जिनके माध्यम से ग्रामीणों और तीर्थयात्रियों को निःशुल्क अथवा सुलभ मूल्य पर पवित्र प्रसाद उपलब्ध कराया जाता था। जयपताका स्वामी ने भक्ति के मानकों की भी रक्षा की और वैदिक दर्शन को समझाने वाली शैक्षिक प्रदर्शनियों की योजना बनाने में सहयोग दिया। यह अध्याय मायापुर को एक विकसित होते आध्यात्मिक नगर के रूप में प्रस्तुत करता है, जहाँ पूजा, शिक्षा, करुणापूर्ण प्रसाद वितरण और भक्तिमय संस्कृति के माध्यम से प्रत्येक राष्ट्र के लोगों की सेवा की जाएगी।",
"‘टेम्पल ऑफ द वैदिक प्लैनेटेरियम’ मायापुर के लिए श्रील प्रभुपाद की एक महान परिकल्पना थी। वे चाहते थे कि वास्तुकला, प्रतिरूपों, कलाकृतियों और शिक्षा के माध्यम से वहाँ वैदिक ब्रह्माण्ड-विज्ञान, दर्शन और आध्यात्मिक जगत को प्रस्तुत किया जाए। मंदिर का उद्देश्य विश्वभर से आगंतुकों को आकर्षित करना और उन्हें श्रीमद्भागवतम की शिक्षाओं को समझाना था। इसके विकास के मार्ग में आर्थिक, राजनीतिक और तकनीकी चुनौतियाँ आईं। तथापि, जयपताका स्वामी इस परियोजना का समर्थन और प्रचार निरंतर करते रहे, क्योंकि वे इसे प्रभुपाद का एक महत्वपूर्ण निर्देश मानते थे। उन्होंने ‘भक्तिवेदान्त स्वामी चैरिटी ट्रस्ट’ के साथ मिलकर श्री चैतन्य महाप्रभु और गौड़ीय वैष्णव परंपरा से संबंधित पवित्र स्थलों की पहचान, पुनर्स्थापना और संरक्षण के लिए भी कार्य किया।",
"जयपताका स्वामी ने भक्तिवेदान्त स्वामी चैरिटी ट्रस्ट के माध्यम से पवित्र स्थलों को संरक्षित करने में सहायता की और इस्कॉन के गवर्निंग बॉडी कमीशन के सदस्य के रूप में सेवा की। वृन्दावन में श्रील प्रभुपाद की अंतिम बीमारी के समय वे अन्य शिष्यों के साथ हरिनाम जप करने, उनके शरीर की मालिश करने और व्यक्तिगत रूप से अपने आध्यात्मिक गुरु की सेवा करने में सम्मिलित हुए। प्रभुपाद के अप्रकट होने से पूर्व जयपताका स्वामी ने उनके चरणों में प्रार्थना की कि उन्हें उनके मिशन को आगे बढ़ाने की शक्ति प्राप्त हो। प्रभुपाद के अप्रकट होने के पश्चात उन्होंने समाधि संस्कारों में भाग लिया और गहरे व्यक्तिगत शोक का सामना किया। प्रभुपाद ने उन्हें शिष्यों को दीक्षा देने और नए भक्तों का मार्गदर्शन करने के लिए अधिकृत किया था। जयपताका स्वामी ने इस उत्तरदायित्व को स्वीकार किया और बाद में गृहस्थ-आधारित भक्त समुदायों का विस्तार करने के एक प्रभावी माध्यम के रूप में नामहट्ट व्यवस्था को विकसित किया।",
"जयपताका स्वामी ने श्रील भक्तिविनोद ठाकुर द्वारा मूल रूप से प्रचारित नामहट्ट व्यवस्था को पुनर्जीवित और विस्तारित किया। ‘नामहट्ट’ का अर्थ है ‘पवित्र नाम का बाजार’। यह गृहस्थों को आश्रमों के बाहर रहते हुए भी कृष्णभावनामृत का अभ्यास करने, परिवार का पालन-पोषण करने, घरों में कार्यक्रम आयोजित करने और मंदिरों का सहयोग करने की सुविधा प्रदान करता है। जयपताका स्वामी ने महत्वपूर्ण गौड़ीय वैष्णव ग्रंथों का अनुवाद और व्याख्या की तथा भक्तों की सहभागिता के लिए व्यवस्थित स्तरों की रचना की। श्रद्धा, भक्ति और श्रीकृष्ण के प्रति प्रेम की आध्यात्मिक अवस्थाओं की तुलना एक बाजार में क्रमशः अधिक मूल्यवान होने वाली वस्तुओं से की गई। नामहट्ट और उससे संबंधित भक्ति-वृक्ष कार्यक्रम के माध्यम से भारत और अन्य देशों में हजारों छोटे भक्त समूह विकसित हुए। इन कार्यक्रमों ने परिवारों और स्थानीय समुदायों के लिए आध्यात्मिक साधना को सुलभ बना दिया।",
"जयपताका स्वामी ने मध्य पूर्व, यूरोप, अमेरिका और अन्य क्षेत्रों में कृष्णभावनामृत का विस्तार करने के लिए व्यापक रूप से यात्रा की। जिन देशों में सार्वजनिक प्रचार पर प्रतिबंध था, वहाँ भक्तों ने निजी घरों में कार्यक्रम आयोजित किए, अनूदित पुस्तकों का वितरण किया और घरों के भीतर उत्सव मनाए। जयपताका स्वामी ने व्यक्तिगत यात्राओं, मार्गदर्शन और संवाद के माध्यम से इन समुदायों को प्रोत्साहित किया। उन्होंने विश्वभर के अनुयायियों के लिए सुलभ बने रहने हेतु प्रारम्भिक समय से ही ई-मेल का भी उपयोग किया। यह अध्याय अटलांटा में आयोजित पानिहाटि चिड़ा-दधि महोत्सव में उनकी सहभागिता का वर्णन करता है, जिसे ‘न्यू पानिहाटि धाम’ के नाम से जाना जाता है। उनके मार्गदर्शन में यह रथ-यात्रा, हरिनाम संकीर्तन, पूजा, प्रसाद और आध्यात्मिक शिक्षा से युक्त एक विशाल भक्तिमय उत्सव के रूप में विकसित हुआ। उनकी यात्राओं ने श्रील प्रभुपाद के मिशन के चारों ओर अंतरराष्ट्रीय भक्त समुदायों को एकजुट करने में सहायता की।",
"सन् 1989 में, मैड्रिड से बार्सिलोना की यात्रा करते समय जयपताका स्वामी पर पीछे से हमला किया गया। एक व्यक्ति ने उनकी गर्दन पर गहरा वार किया, जिससे महत्वपूर्ण रक्तवाहिनियाँ क्षतिग्रस्त हो गईं। अत्यधिक रक्तस्राव होने और बोलने में असमर्थ होने के बावजूद उन्होंने अपने वस्त्र को घाव के चारों ओर बाँध लिया और मन ही मन हरे कृष्ण महामंत्र का जप करते रहे। उन्होंने श्रील प्रभुपाद और मायापुर में अपने अधूरे उत्तरदायित्वों का स्मरण किया। आपातकालीन शल्य-चिकित्सा ने उनके जीवन की रक्षा की, और चिकित्सकों ने उनके जीवित बचने को असाधारण माना। प्रारम्भ में कुछ झूठी रिपोर्टों में हमलावर को इस्कॉन से जोड़ा गया था, किंतु जयपताका स्वामी ने अस्पताल से ही प्रेस कॉन्फ्रेंस में भाग लेकर उस गलत जानकारी को ठीक किया। विश्वभर के भक्तों ने उनके लिए प्रार्थना की। उपचार और पुनर्वास के पश्चात उन्होंने नवीन दृढ़ संकल्प के साथ पुनः यात्रा, शिक्षण और प्रचार आरम्भ किया।",
"सन् 2008 में मुंबई में जयपताका स्वामी को गंभीर मस्तिष्क रक्तस्राव हुआ। उन्होंने अपनी चलने-फिरने और बोलने की क्षमता का बहुत बड़ा भाग खो दिया, किंतु वे अपने आध्यात्मिक कर्तव्यों के प्रति सचेत रहे। उनकी प्रारम्भिक माँगों में से एक जप की संख्या गिनने के लिए एक गणना-यंत्र था, जिससे वे अपना जप जारी रख सकें। गहन उपचार और पुनर्वास के माध्यम से वे धीरे-धीरे स्वस्थ हुए और पुनः प्रचार आरम्भ किया। वे प्रत्येक शारीरिक व्यायाम को श्रीकृष्ण के पवित्र नाम से जोड़ते थे। बाद में उनके यकृत और गुर्दों में गंभीर समस्याएँ उत्पन्न हुईं, जिसका एक कारण पूर्व में रक्त चढ़ाने के माध्यम से हुआ हेपेटाइटिस संक्रमण था। सन् 2018 में उनका सफलतापूर्वक यकृत और गुर्दा प्रत्यारोपण किया गया। निरंतर शारीरिक सीमाओं और व्हीलचेयर का उपयोग करने के बावजूद, जयपताका स्वामी ने यात्रा करना, शिष्यों को शिक्षा देना और श्रील प्रभुपाद के मायापुर मिशन की सेवा करना जारी रखा।",
]

assert len(BENGALI) == len(HINDI) == len(TITLES_IN_ORDER) == 13

def esc(s):
    return s.replace("\\", "\\\\").replace('"', '\\"')

start = html.find("const LEVELS = [")
end = html.find("\n];", start)
if start == -1 or end == -1:
    print("ERROR: could not find the LEVELS array.")
    sys.exit(1)
levels_block = html[start:end]

missing = []
for i, title in enumerate(TITLES_IN_ORDER):
    title_pos = levels_block.find('title:"' + title + '"')
    if title_pos == -1:
        print("WARNING: stage \"" + title + "\" not found at all.")
        continue
    next_title_pos = levels_block.find('title:"', title_pos+1)
    obj_end = next_title_pos if next_title_pos != -1 else len(levels_block)
    segment = levels_block[title_pos:obj_end]
    has_bengali = 'bengali:"' in segment
    has_hindi = 'hindi:"' in segment
    status = "OK" if (has_bengali and has_hindi) else "MISSING"
    print("Stage " + str(i+1) + " \"" + title + "\": bengali=" + str(has_bengali) + ", hindi=" + str(has_hindi) + " -> " + status)
    if not (has_bengali and has_hindi):
        missing.append(i)

if missing:
    print("")
    print(str(len(missing)) + " stage(s) missing translations -- re-applying now.")
    for i in missing:
        title = TITLES_IN_ORDER[i]
        title_pos = levels_block.find('title:"' + title + '"')
        insp_pos = levels_block.find('inspiration:"', title_pos)
        if insp_pos == -1:
            print("  WARNING: could not find inspiration field for \"" + title + "\" -- skipping.")
            continue
        j = insp_pos + len('inspiration:"')
        while True:
            j = levels_block.find('"', j)
            if levels_block[j-1] != "\\":
                break
            j += 1
        insert_at = j + 1
        new_fields = ',\n  bengali:"' + esc(BENGALI[i]) + '",\n  hindi:"' + esc(HINDI[i]) + '"'
        levels_block = levels_block[:insert_at] + new_fields + levels_block[insert_at:]
    html = html[:start] + levels_block + html[end:]
    print("Re-applied missing translations.")
else:
    print("")
    print("All 13 stages already have Bengali and Hindi text present -- data is fine.")

lang_row_pattern = re.compile(r'<div id="introLangRow"[^>]*>.*?</div>', re.DOTALL)
lr_match = lang_row_pattern.search(html)
if not lr_match:
    print("ERROR: could not find the #introLangRow block to move. No HTML position change made.")
else:
    lang_row_html = lr_match.group(0)
    html = html[:lr_match.start()] + html[lr_match.end():]
    meta_anchor = '<div class="intro-meta" id="introMeta"></div>'
    if meta_anchor not in html:
        print("ERROR: could not find the chapter title element. Language row removed but not re-inserted -- STOPPING without saving to avoid losing it.")
        sys.exit(1)
    html = html.replace(meta_anchor, meta_anchor + "\n    " + lang_row_html, 1)
    print("Moved the language selector to directly below the chapter title.")

render_count = html.count("function renderStoryText(lv){")
print("")
print("renderStoryText function present: " + str(render_count) + " time(s) (should be 1)")
print("Language button wiring present: " + ("yes" if "introLangRow .lang-btn" in html else "no"))

with open(TARGET, "w", encoding="utf-8") as f:
    f.write(html)

print("")
print("Done. www/index.html has been updated and written to disk.")
print("Next: git add -A && git commit -m 'Fix language selector position and Bengali/Hindi display' && git push")
